        lines = [f.readline() for _ in range(20)]
    return pd.DataFrame({'raw_lines': lines})

def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_lightning_caused_acres.csv', 'r') as f:
        lines = [f.readline() for _ in range(20)]
    return pd.DataFrame({'raw_lines': lines})

def process(human_caused, lightning_caused) -> pd.DataFrame:
    human = human_caused.copy()
    lightning = lightning_caused.copy()

    # Clean numeric columns - remove commas and convert to numeric
    for col in human.columns:
        if col != 'Year':
            human[col] = pd.to_numeric(human[col].astype(str).str.replace(',', ''), errors='coerce')

    for col in lightning.columns:
        if col != 'Year':
            lightning[col] = pd.to_numeric(lightning[col].astype(str).str.replace(',', ''), errors='coerce')

    # Combine human and lightning caused acres
    combined = pd.DataFrame({'Year': human['Year']})

    # Get geographic areas (all columns except Year and Total)
    geo_areas = [col for col in human.columns if col not in ['Year', 'Total']]

    for area in geo_areas:
        human_val = human[area].fillna(0)
        lightning_val = lightning[area].fillna(0)
        combined[area] = human_val + lightning_val

    combined['Total'] = combined[geo_areas].sum(axis=1)

    return combined

def process(human_caused, lightning_caused) -> pd.DataFrame:
    human = human_caused.copy()
    lightning = lightning_caused.copy()

    # Clean numeric columns - remove commas and convert to numeric
    for col in human.columns:
        if col != 'Year':
            human[col] = human[col].astype(str).str.replace(',', '', regex=False)
            human[col] = pd.to_numeric(human[col], errors='coerce')

    for col in lightning.columns:
        if col != 'Year':
            lightning[col] = lightning[col].astype(str).str.replace(',', '', regex=False)
            lightning[col] = pd.to_numeric(lightning[col], errors='coerce')

    # Get geographic areas - exclude Year and Total
    human_areas = [col for col in human.columns if col not in ['Year', 'Total']]
    lightning_areas = [col for col in lightning.columns if col not in ['Year', 'Total']]

    combined = human[['Year']].copy()

    # Match columns between datasets, accounting for 'Western Great Basin' vs 'Western Great Basin*'
    for area in human_areas:
        human_val = human[area].fillna(0)
        # For lightning, check if the column exists as-is or with asterisk
        if area in lightning.columns:
            lightning_val = lightning[area].fillna(0)
        elif area + '*' in lightning.columns:
            lightning_val = lightning[area + '*'].fillna(0)
        else:
            lightning_val = 0
        combined[area] = human_val + lightning_val

    combined['Total'] = combined[[col for col in combined.columns if col != 'Year']].sum(axis=1)

    return combined
